def test_jbd2_prefix_torn_anchor_install_is_retryable(
    replay_fixture: dict[str, object],
    tmp_path: Path,
    phase: str,
    write_ordinal: int,
    byte_index: int,
) -> None:
    image = replay_fixture["image"]
