def _assert_unlinked_cleanup_media_converges(
    interrupted: Path,
    repaired: Path,
    stable: Path,
    *,
    expectation: dict[str, object],
) -> tuple[tuple[tuple[str, int, int], ...], str]:
    protocol = expectation["protocol"]
    source = expectation["source"]
    patches = expectation["patches"]
    clean_image = expectation["clean_image"]
    block_size = expectation["block_size"]
    inode_home = expectation["inode_home"]
    inode_bitmap_home = expectation["inode_bitmap_home"]
    block_bitmap_home = expectation["block_bitmap_home"]
    data_block = expectation["data_block"]
    data_bitmap_byte = expectation["data_bitmap_byte"]
    data_bitmap_mask = expectation["data_bitmap_mask"]
    inode_group = expectation["inode_group"]
    data_group = expectation["data_group"]
    inode_gdt_home = expectation["inode_gdt_home"]
    data_gdt_home = expectation["data_gdt_home"]
    expected_data_group_free_blocks = expectation[
        "expected_data_group_free_blocks"
    ]
    expected_inode_group_free_blocks = expectation[
        "expected_inode_group_free_blocks"
    ]
    expected_group_free = expectation["expected_group_free"]
    expected_itable_unused = expectation["expected_itable_unused"]
    expected_super_free_blocks = expectation["expected_super_free_blocks"]
    expected_super_free = expectation["expected_super_free"]
    assert protocol in {"modern", "legacy"}
    assert isinstance(source, Path)
    assert isinstance(patches, tuple)
    assert isinstance(clean_image, Path)
    assert isinstance(block_size, int)
    assert isinstance(inode_home, int)
    assert isinstance(inode_bitmap_home, int)
    assert isinstance(block_bitmap_home, int)
    assert data_block is None or isinstance(data_block, int)
    assert isinstance(data_bitmap_byte, int)
    assert isinstance(data_bitmap_mask, int)
    assert isinstance(inode_group, int)
    assert isinstance(data_group, int)
    assert isinstance(inode_gdt_home, int)
    assert isinstance(data_gdt_home, int)
    assert isinstance(expected_data_group_free_blocks, int)
    assert isinstance(expected_inode_group_free_blocks, int)
    assert isinstance(expected_group_free, int)
    assert isinstance(expected_itable_unused, int)
    assert isinstance(expected_super_free_blocks, int)
    assert isinstance(expected_super_free, int)
    inode_bitmap_byte, inode_bitmap_bit = divmod(18 - 1, 8)
    inode_bitmap_mask = 1 << inode_bitmap_bit
    repaired_marker = (
        f"EXT4-{protocol.upper()}-UNLINKED-PREFIX-REPAIRED"
    )
    stable_marker = f"EXT4-{protocol.upper()}-UNLINKED-PREFIX-STABLE"
    output, repair_trace, repaired_sha256 = run_recovery_forth(
        interrupted,
        repaired,
        [
            "T-ARENA CONSTANT _UA-ARENA",
            (
                "_UA-ARENA T-VOLUME EXT4-NEW "
                "CONSTANT _UA-IOR CONSTANT _UA-V"
            ),
            "_UA-V _EXT4-CTX CONSTANT _UA-CTX",
            "18 _UA-CTX _EXT4-LOAD-INODE CONSTANT _UA-INODE-IOR",
            (
                f"{inode_group} _UA-CTX _EXT4-LOAD-INODE-BITMAP "
                "CONSTANT _UA-BITMAP-IOR CONSTANT _UA-BITMAP-HOME"
            ),
            (
                f"_UA-CTX _EXT4-C.BLOCK + {inode_bitmap_byte} + C@ "
                f"{inode_bitmap_mask} AND "
                "CONSTANT _UA-INODE-BIT"
            ),
            *(
                [
                    (
                        f"{data_group} _UA-CTX _EXT4-LOAD-BLOCK-BITMAP "
                        "CONSTANT _UA-DATA-BITMAP-IOR "
                        "CONSTANT _UA-DATA-BITMAP-HOME"
                    ),
                    (
                        f"_UA-CTX _EXT4-C.BLOCK + {data_bitmap_byte} + C@ "
                        f"{data_bitmap_mask} AND CONSTANT _UA-DATA-BIT"
                    ),
                ]
                if data_block is not None
                else []
            ),
            (
                f"{data_group} _UA-CTX _EXT4-LOAD-DESC "
                "CONSTANT _UA-DATA-DESC-IOR"
            ),
            (
                "_UA-CTX _EXT4-C.DESC + _EXT4-JFB-DESC-FREE@ "
                "CONSTANT _UA-DATA-GROUP-FREE-BLOCKS"
            ),
            (
                f"{inode_group} _UA-CTX _EXT4-LOAD-DESC "
                "CONSTANT _UA-INODE-DESC-IOR"
            ),
            (
                _forth_conjunction(
                    [
                        "_UA-IOR 0=",
                        "_UA-V V.LIFECYCLE @ VFS-L-MOUNTED =",
                        "_UA-V _EXT4-READY?",
                        "_UA-V _EXT4-ATTACHED?",
                        "_UA-V V.FLAGS @ VFS-F-DIRTY AND 0=",
                        "_UA-CTX _EXT4-C.RECOVERY + @ 0=",
                        "_UA-CTX _EXT4-C.J.WRITE-ACTIVE + @ 0=",
                        "_UA-CTX _EXT4-C.J.WRITER-CURRENT + @ -1 =",
                        "_UA-CTX _EXT4-C.J.WRITER + @ 0=",
                        "_UA-CTX _EXT4-C.J.START + @ 0=",
                        "_UA-CTX _EXT4-C.J.ANCHOR + @ 0=",
                        "_UA-CTX _EXT4-C.J.WITNESS + @ 0=",
                        "_UA-CTX _EXT4-C.J.CLEANUP + @ 0=",
                        "_UA-CTX _EXT4-C.J.PRIMARY-TORN + @ 0=",
                        "_UA-CTX _EXT4-C.SUPER-TORN + @ 0=",
                        "_UA-CTX _EXT4-C.O.ACTIVE + @ 0=",
                        "_UA-CTX _EXT4-C.O.MODERN-ACTIVE + @ 0=",
                        "_UA-CTX _EXT4-C.O.LEGACY-ACTIVE + @ 0=",
                        "_UA-CTX _EXT4-C.O.CLEAR-PENDING + @ 0=",
                        "_UA-CTX _EXT4-C.ARENA + @ _UA-ARENA =",
                        "_EXT4-MOC-MARK-VALID @ 0=",
                        "_EXT4-JFO-CERT-SCOPE @ 0=",
                        "_EXT4-JFO-CERT-VALID @ 0=",
                        *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                        (
                            "_UA-CTX _EXT4-C.SB + "
                            "_EXT4-SB.LAST-ORPHAN + L@ 0="
                        ),
                        (
                            "_UA-CTX _EXT4-C.SB + "
                            "_EXT4-SB.INCOMPAT + L@ "
                            "_EXT4-INCOMPAT-RECOVER AND 0="
                        ),
                        (
                            "_UA-CTX _EXT4-C.SB + "
                            "_EXT4-SB.RO-COMPAT + L@ "
                            "_EXT4-RO-ORPHAN-PRESENT AND 0="
                        ),
                        (
                            "_UA-INODE-IOR VFS-IOR-REASON "
                            "VFS-R-CORRUPT ="
                        ),
                        (
                            "_UA-INODE-IOR VFS-IOR-DETAIL "
                            "EXT4-D-BOUNDS ="
                        ),
                        "_UA-BITMAP-IOR 0=",
                        f"_UA-BITMAP-HOME {inode_bitmap_home} =",
                        "_UA-INODE-BIT 0=",
                        *(
                            [
                                "_UA-DATA-BITMAP-IOR 0=",
                                (
                                    "_UA-DATA-BITMAP-HOME "
                                    f"{block_bitmap_home} ="
                                ),
                                "_UA-DATA-BIT 0=",
                            ]
                            if data_block is not None
                            else []
                        ),
                        "_UA-DATA-DESC-IOR 0=",
                        "_UA-INODE-DESC-IOR 0=",
                        (
                            "_UA-DATA-GROUP-FREE-BLOCKS "
                            f"{expected_data_group_free_blocks} ="
                        ),
                        (
                            "_UA-CTX _EXT4-C.DESC + "
                            "_EXT4-JFI-DESC-FREE@ "
                            f"{expected_group_free} ="
                        ),
                        (
                            "_UA-CTX _EXT4-C.DESC + "
                            "_EXT4-JFB-DESC-FREE@ "
                            f"{expected_inode_group_free_blocks} ="
                        ),
                        (
                            "_UA-CTX _EXT4-C.DESC + "
                            "_EXT4-GD.ITABLE-UNUSED-LO + W@ "
                            f"{expected_itable_unused & 0xFFFF} ="
                        ),
                        (
                            "_UA-CTX _EXT4-C.DESC + "
                            "_EXT4-GD.ITABLE-UNUSED-HI + W@ "
                            f"{expected_itable_unused >> 16} ="
                        ),
                        (
                            "_UA-CTX _EXT4-C.FREE-INODES + @ "
                            f"{expected_super_free} ="
                        ),
                        (
                            "_UA-CTX _EXT4-C.FREE-BLOCKS + @ "
                            f"{expected_super_free_blocks} ="
                        ),
                    ]
                )
                + f' IF ." {repaired_marker}" THEN'
            ),
        ],
        capture_media=repaired,
    )
    _assert_emitted(output, repaired_marker)
    assert repaired.is_file()
    assert _sha256(repaired) == repaired_sha256
    _, reclaimed_inode, _ = _ext4_inode_record(repaired, 18)
    assert reclaimed_inode == bytes(256)
    with source.open("rb") as canonical_media:
        canonical_media.seek(inode_home * block_size)
        canonical_inode_home = canonical_media.read(block_size)
    with repaired.open("rb") as repaired_media:
        repaired_media.seek(inode_home * block_size)
        repaired_inode_home = repaired_media.read(block_size)
    assert repaired_inode_home == canonical_inode_home
    if data_block is not None:
        expected_data = dict(patches).get(data_block * block_size)
        if expected_data is None:
            with source.open("rb") as canonical_media:
                canonical_media.seek(data_block * block_size)
                expected_data = canonical_media.read(block_size)
        assert len(expected_data) == block_size
        with repaired.open("rb") as repaired_media:
            repaired_media.seek(data_block * block_size)
            repaired_data = repaired_media.read(block_size)
        assert repaired_data == expected_data
    for gdt_home in {inode_gdt_home, data_gdt_home}:
        with clean_image.open("rb") as clean_media:
            clean_media.seek(gdt_home * block_size)
            expected_gdt = clean_media.read(block_size)
        with repaired.open("rb") as repaired_media:
            repaired_media.seek(gdt_home * block_size)
            repaired_gdt = repaired_media.read(block_size)
        assert repaired_gdt == expected_gdt

    stable_output, stable_trace, stable_sha256 = run_recovery_forth(
        repaired,
        stable,
        [
            "T-ARENA T-VOLUME EXT4-NEW CONSTANT _UB-IOR CONSTANT _UB-V",
            "_UB-V _EXT4-CTX CONSTANT _UB-CTX",
            "18 _UB-CTX _EXT4-LOAD-INODE CONSTANT _UB-INODE-IOR",
            (
                _forth_conjunction(
                    [
                        "_UB-IOR 0=",
                        "_UB-V V.LIFECYCLE @ VFS-L-MOUNTED =",
                        "_UB-V _EXT4-READY?",
                        "_UB-CTX _EXT4-C.J.WRITER + @ 0=",
                        "_EXT4-JFO-CERT-SCOPE @ 0=",
                        "_EXT4-JFO-CERT-VALID @ 0=",
                        *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                        (
                            "_UB-INODE-IOR VFS-IOR-REASON "
                            "VFS-R-CORRUPT ="
                        ),
                        (
                            "_UB-INODE-IOR VFS-IOR-DETAIL "
                            "EXT4-D-BOUNDS ="
                        ),
                        (
                            "_UB-CTX _EXT4-C.FREE-INODES + @ "
                            f"{expected_super_free} ="
                        ),
                        (
                            "_UB-CTX _EXT4-C.FREE-BLOCKS + @ "
                            f"{expected_super_free_blocks} ="
                        ),
                    ]
                )
                + f' IF ." {stable_marker}" THEN'
            ),
        ],
        capture_media=stable,
    )
    _assert_emitted(stable_output, stable_marker)
    assert stable_trace == ()
    assert stable_sha256 == repaired_sha256
    return repair_trace, repaired_sha256


def _write_ordinals_for_ext4_home(
    trace: tuple[tuple[str, int, int], ...],
    home: int,
    *,
    block_size: int = 1024,
) -> tuple[int, ...]:
    sectors_per_block = block_size // 512
    target_first = home * sectors_per_block
    target_limit = target_first + sectors_per_block
    write_ordinal = 0
    matches: list[int] = []
    for kind, first_sector, sector_count in trace:
        if kind != "write":
            continue
        write_ordinal += 1
        write_limit = first_sector + sector_count
        if first_sector < target_limit and target_first < write_limit:
            matches.append(write_ordinal)
    return tuple(matches)


def _trace_event_index_for_ordinal(
    trace: tuple[tuple[str, int, int], ...],
    kind: str,
    ordinal: int,
) -> int:
    assert kind in {"write", "flush"}
    assert ordinal > 0
    seen = 0
    for index, event in enumerate(trace):
        if event[0] != kind:
            continue
        seen += 1
        if seen == ordinal:
            return index
    raise AssertionError(f"trace has no {kind} ordinal {ordinal}")


def _trace_ordinal_at_event(
    trace: tuple[tuple[str, int, int], ...],
    kind: str,
    event_index: int,
) -> int:
    assert kind in {"write", "flush"}
    assert 0 <= event_index < len(trace)
    assert trace[event_index][0] == kind
    return sum(event[0] == kind for event in trace[: event_index + 1])


def _linked_first_more_trace_points(
    expectation: dict[str, object],
) -> dict[str, dict[str, int]]:
    protocol = expectation["protocol"]
    assert protocol in {"modern", "legacy"}
    trace = expectation["success_trace"]
    inode18_home = expectation["inode18_home"]
    gdt_home = expectation["gdt_home"]
    block_bitmap_home = expectation["block_bitmap_home"]
    orphan_home = expectation["orphan_home"]
    data_block = expectation["data_block"]
    assert isinstance(trace, tuple)
    assert isinstance(inode18_home, int)
    assert isinstance(gdt_home, int)
    assert isinstance(block_bitmap_home, int)
    assert isinstance(orphan_home, int)
    assert isinstance(data_block, int)

    inode18_writes = _write_ordinals_for_ext4_home(trace, inode18_home)
    gdt_writes = _write_ordinals_for_ext4_home(trace, gdt_home)
    bitmap_writes = _write_ordinals_for_ext4_home(
        trace,
        block_bitmap_home,
    )
    super_writes = _write_ordinals_for_ext4_home(trace, 1)
    orphan_writes = _write_ordinals_for_ext4_home(trace, orphan_home)
    assert len(inode18_writes) == len(gdt_writes) == len(bitmap_writes) == 1
    assert len(super_writes) == (3 if protocol == "modern" else 4)
    assert len(orphan_writes) == (2 if protocol == "modern" else 0)
    inode18_write = inode18_writes[0]
    gdt_write = gdt_writes[0]
    bitmap_write = bitmap_writes[0]
    more_super_write = super_writes[1]
    first_home_writes = (
        inode18_write,
        gdt_write,
        bitmap_write,
        more_super_write,
    )
    if protocol == "modern":
        first_home_writes += (orphan_writes[0],)
    assert first_home_writes == tuple(
        range(inode18_write, inode18_write + len(first_home_writes))
    )
    assert super_writes[0] < inode18_write
    if protocol == "modern":
        assert more_super_write < orphan_writes[0] < orphan_writes[1]
        assert orphan_writes[1] < super_writes[2]
    else:
        assert more_super_write < super_writes[2] < super_writes[3]
    assert not _write_ordinals_for_ext4_home(trace, data_block)

    commit_write = inode18_write - 1
    commit_event = _trace_event_index_for_ordinal(
        trace,
        "write",
        commit_write,
    )
    inode18_event = _trace_event_index_for_ordinal(
        trace,
        "write",
        inode18_write,
    )
    last_more_home_write = first_home_writes[-1]
    last_more_home_event = _trace_event_index_for_ordinal(
        trace,
        "write",
        last_more_home_write,
    )
    assert inode18_event == commit_event + 2
    assert trace[commit_event + 1] == ("flush", 0, 0)
    assert trace[last_more_home_event + 1] == ("flush", 0, 0)

    suffix_start = last_more_home_event + 2
    suffix = trace[suffix_start : suffix_start + 10]
    assert len(suffix) == 10
    assert tuple(event[0] for event in suffix) == (
        "write",
        "flush",
        "write",
        "flush",
        "write",
        "flush",
        "write",
        "flush",
        "write",
        "flush",
    )
    reset_anchor_sector = suffix[0][1]
    journal_primary_sector = suffix[4][1]
    assert reset_anchor_sector != journal_primary_sector
    assert suffix[0] == suffix[2]
    assert suffix[4] == suffix[6]
    assert suffix[8] == suffix[0]
    assert all(event[2] == 2 for event in suffix[::2])

    flush_events = {
        "commit": commit_event + 1,
        "homes": last_more_home_event + 1,
        "reset-preseed": suffix_start + 1,
        "reset-anchor": suffix_start + 3,
        "reset-primary": suffix_start + 5,
        "witness-clear": suffix_start + 7,
        "guard-retire": suffix_start + 9,
    }
    writes = {
        "commit": commit_write,
        "inode": inode18_write,
        "gdt": gdt_write,
        "bitmap": bitmap_write,
        "super": more_super_write,
        "reset-primary": _trace_ordinal_at_event(
            trace,
            "write",
            suffix_start + 4,
        ),
        "witness-clear": _trace_ordinal_at_event(
            trace,
            "write",
            suffix_start + 6,
        ),
        "guard-retire": _trace_ordinal_at_event(
            trace,
            "write",
            suffix_start + 8,
        ),
    }
    if protocol == "modern":
        writes["orphan"] = orphan_writes[0]
    return {
        "writes": writes,
        "flushes": {
            name: _trace_ordinal_at_event(trace, "flush", event_index)
            for name, event_index in flush_events.items()
        },
        "flush_events": flush_events,
    }


def _assert_multi_empty_cleanup_media_converges(
    interrupted: Path,
    repaired: Path,
    stable: Path,
    *,
    expectation: dict[str, object],
) -> None:
    source = expectation["source"]
    block_size = expectation["block_size"]
    inode18_home = expectation["inode18_home"]
    inode21_home = expectation["inode21_home"]
    inode_bitmap_home = expectation["inode_bitmap_home"]
    gdt_home = expectation["gdt_home"]
    orphan_home = expectation["orphan_home"]
    canonical_group_free = expectation["canonical_group_free"]
    canonical_super_free = expectation["canonical_super_free"]
    expected_itable_unused = expectation["expected_itable_unused"]
    expected_gdt = expectation["expected_gdt"]
    assert isinstance(source, Path)
    assert block_size == 1024
    assert isinstance(inode18_home, int)
    assert isinstance(inode21_home, int)
    assert isinstance(inode_bitmap_home, int)
    assert isinstance(gdt_home, int)
    assert isinstance(orphan_home, int)
    assert isinstance(canonical_group_free, int)
    assert isinstance(canonical_super_free, int)
    assert isinstance(expected_itable_unused, int)
    assert isinstance(expected_gdt, bytes)

    marker = "EXT4-MIXED-MULTI-ORPHAN-CRASH-REPAIRED"
    output, _repair_trace, repaired_sha256 = run_recovery_forth(
        interrupted,
        repaired,
        [
            "T-ARENA T-VOLUME EXT4-NEW CONSTANT _MCR-IOR CONSTANT _MCR-V",
            "_MCR-V _EXT4-CTX CONSTANT _MCR-CTX",
            "18 _MCR-CTX _EXT4-LOAD-INODE CONSTANT _MCR-I18-IOR",
            "21 _MCR-CTX _EXT4-LOAD-INODE CONSTANT _MCR-I21-IOR",
            (
                "0 _MCR-CTX _EXT4-LOAD-INODE-BITMAP "
                "CONSTANT _MCR-BITMAP-IOR CONSTANT _MCR-BITMAP-HOME"
            ),
            "_MCR-CTX _EXT4-C.BLOCK + 2 + C@ CONSTANT _MCR-INODE-BITS",
            "0 _MCR-CTX _EXT4-LOAD-DESC CONSTANT _MCR-DESC-IOR",
            (
                _forth_conjunction(
                    [
                        "_MCR-IOR 0=",
                        "_MCR-V V.LIFECYCLE @ VFS-L-MOUNTED =",
                        "_MCR-V _EXT4-READY?",
                        "_MCR-V _EXT4-ATTACHED?",
                        "_MCR-V V.FLAGS @ VFS-F-DIRTY AND 0=",
                        "_MCR-CTX _EXT4-C.RECOVERY + @ 0=",
                        "_MCR-CTX _EXT4-C.J.WRITE-ACTIVE + @ 0=",
                        "_MCR-CTX _EXT4-C.J.WRITER + @ 0=",
                        "_MCR-CTX _EXT4-C.O.ACTIVE + @ 0=",
                        "_MCR-CTX _EXT4-C.O.MODERN-ACTIVE + @ 0=",
                        "_MCR-CTX _EXT4-C.O.LEGACY-ACTIVE + @ 0=",
                        "_MCR-CTX _EXT4-C.O.CLEAR-PENDING + @ 0=",
                        (
                            "_MCR-CTX _EXT4-C.SB + "
                            "_EXT4-SB.LAST-ORPHAN + L@ 0="
                        ),
                        (
                            "_MCR-CTX _EXT4-C.SB + _EXT4-SB.INCOMPAT + L@ "
                            "_EXT4-INCOMPAT-RECOVER AND 0="
                        ),
                        (
                            "_MCR-CTX _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@ "
                            "_EXT4-RO-ORPHAN-PRESENT AND 0="
                        ),
                        (
                            "_MCR-I18-IOR VFS-IOR-REASON "
                            "VFS-R-CORRUPT ="
                        ),
                        (
                            "_MCR-I18-IOR VFS-IOR-DETAIL "
                            "EXT4-D-BOUNDS ="
                        ),
                        (
                            "_MCR-I21-IOR VFS-IOR-REASON "
                            "VFS-R-CORRUPT ="
                        ),
                        (
                            "_MCR-I21-IOR VFS-IOR-DETAIL "
                            "EXT4-D-BOUNDS ="
                        ),
                        "_MCR-BITMAP-IOR 0=",
                        f"_MCR-BITMAP-HOME {inode_bitmap_home} =",
                        "_MCR-INODE-BITS 0x12 AND 0=",
                        "_MCR-DESC-IOR 0=",
                        (
                            "_MCR-CTX _EXT4-C.DESC + "
                            "_EXT4-JFI-DESC-FREE@ "
                            f"{canonical_group_free} ="
                        ),
                        (
                            "_MCR-CTX _EXT4-C.DESC + DUP "
                            "_EXT4-GD.ITABLE-UNUSED-LO + W@ SWAP "
                            "_EXT4-GD.ITABLE-UNUSED-HI + W@ "
                            "16 LSHIFT OR "
                            f"{expected_itable_unused} ="
                        ),
                        (
                            "_MCR-CTX _EXT4-C.FREE-INODES + @ "
                            f"{canonical_super_free} ="
                        ),
                    ]
                )
                + f' IF ." {marker}" THEN'
            ),
        ],
        capture_media=repaired,
    )
    _assert_emitted(output, marker)
    assert _sha256(repaired) == repaired_sha256
    for inode_number in (18, 21):
        _, inode, _ = _ext4_inode_record(repaired, inode_number)
        assert inode == bytes(256)
    for home in (inode18_home, inode21_home, inode_bitmap_home, orphan_home):
        with source.open("rb") as canonical_media:
            canonical_media.seek(home * block_size)
            canonical_home = canonical_media.read(block_size)
        with repaired.open("rb") as repaired_media:
            repaired_media.seek(home * block_size)
            repaired_home = repaired_media.read(block_size)
        assert repaired_home == canonical_home
    with repaired.open("rb") as repaired_media:
        repaired_media.seek(gdt_home * block_size)
        repaired_gdt = repaired_media.read(block_size)
    assert repaired_gdt == expected_gdt

    stable_marker = "EXT4-MIXED-MULTI-ORPHAN-CRASH-STABLE"
    stable_output, stable_trace, stable_sha256 = run_recovery_forth(
        repaired,
        stable,
        [
            "T-ARENA T-VOLUME EXT4-NEW CONSTANT _MCS-IOR CONSTANT _MCS-V",
            (
                _forth_conjunction(
                    [
                        "_MCS-IOR 0=",
                        "_MCS-V V.LIFECYCLE @ VFS-L-MOUNTED =",
                        "_MCS-V _EXT4-READY?",
                        "_MCS-V _EXT4-CTX _EXT4-C.J.WRITER + @ 0=",
                    ]
                )
                + f' IF ." {stable_marker}" THEN'
            ),
        ],
        capture_media=stable,
    )
    _assert_emitted(stable_output, stable_marker)
    assert stable_trace == ()
    assert stable_sha256 == repaired_sha256
    assert _sha256(stable) == repaired_sha256


def _assert_multi_linked_cleanup_media_converges(
    interrupted: Path,
    repaired: Path,
    stable: Path,
    *,
    expectation: dict[str, object],
) -> None:
    protocol = expectation["protocol"]
    assert protocol in {"modern", "legacy"}
    protocol_tag = str(protocol).upper()
    clean_image = expectation["clean_image"]
    block_size = expectation["block_size"]
    inode18_home = expectation["inode18_home"]
    inode21_home = expectation["inode21_home"]
    block_bitmap_home = expectation["block_bitmap_home"]
    inode_bitmap_home = expectation["inode_bitmap_home"]
    gdt_home = expectation["gdt_home"]
    orphan_home = expectation["orphan_home"]
    data_block = expectation["data_block"]
    data_blocks = expectation["data_blocks"]
    data_bitmap_byte = expectation["data_bitmap_byte"]
    data_bitmap_mask = expectation["data_bitmap_mask"]
    assert isinstance(clean_image, Path)
    assert block_size == 1024
    assert isinstance(inode18_home, int)
    assert isinstance(inode21_home, int)
    assert isinstance(block_bitmap_home, int)
    assert isinstance(inode_bitmap_home, int)
    assert isinstance(gdt_home, int)
    assert isinstance(orphan_home, int)
    assert isinstance(data_block, int)
    assert data_blocks == (data_block,)
    assert isinstance(data_bitmap_byte, int)
    assert isinstance(data_bitmap_mask, int)

    marker = f"EXT4-LINKED-{protocol_tag}-FIRST-MORE-CRASH-REPAIRED"
    output, repair_trace, repaired_sha256 = run_recovery_forth(
        interrupted,
        repaired,
        [
            "T-ARENA CONSTANT _LR-ARENA",
            (
                "_LR-ARENA T-VOLUME EXT4-NEW "
                "CONSTANT _LR-IOR CONSTANT _LR-V"
            ),
            "_LR-V _EXT4-CTX CONSTANT _LR-CTX",
            "18 _LR-CTX _EXT4-LOAD-INODE CONSTANT _LR-I18-IOR",
            (
                "_LR-CTX _EXT4-C.INODE + _EXT4-I.DTIME + L@ "
                "CONSTANT _LR-I18-DTIME"
            ),
            (
                "_LR-CTX _EXT4-C.INODE + _EXT4-I.LINKS + W@ "
                "CONSTANT _LR-I18-LINKS"
            ),
            (
                "_LR-CTX _EXT4-C.INODE + _EXT4-I.SIZE-LO + L@ "
                "CONSTANT _LR-I18-SIZE-LO"
            ),
            (
                "_LR-CTX _EXT4-C.INODE + _EXT4-I.SIZE-HI + L@ "
                "CONSTANT _LR-I18-SIZE-HI"
            ),
            (
                "_LR-CTX _EXT4-C.INODE + _EXT4-I.BLOCKS-LO + L@ "
                "CONSTANT _LR-I18-BLOCKS-LO"
            ),
            (
                "_LR-CTX _EXT4-C.INODE + _EXT4-I.BLOCKS-HI + W@ "
                "CONSTANT _LR-I18-BLOCKS-HI"
            ),
            (
                "_LR-CTX _EXT4-C.INODE + _EXT4-I.BLOCK + 2 + W@ "
                "CONSTANT _LR-I18-ENTRIES"
            ),
            "21 _LR-CTX _EXT4-LOAD-INODE CONSTANT _LR-I21-IOR",
            (
                "_LR-CTX _EXT4-C.INODE + _EXT4-I.DTIME + L@ "
                "CONSTANT _LR-I21-DTIME"
            ),
            (
                "_LR-CTX _EXT4-C.INODE + _EXT4-I.LINKS + W@ "
                "CONSTANT _LR-I21-LINKS"
            ),
            (
                "_LR-CTX _EXT4-C.INODE + _EXT4-I.BLOCK + 2 + W@ "
                "CONSTANT _LR-I21-ENTRIES"
            ),
            (
                "0 _LR-CTX _EXT4-LOAD-BLOCK-BITMAP "
                "CONSTANT _LR-DATA-BITMAP-IOR "
                "CONSTANT _LR-DATA-BITMAP-HOME"
            ),
            (
                f"_LR-CTX _EXT4-C.BLOCK + {data_bitmap_byte} + C@ "
                f"{data_bitmap_mask} AND CONSTANT _LR-DATA-BIT"
            ),
            (
                "0 _LR-CTX _EXT4-LOAD-INODE-BITMAP "
                "CONSTANT _LR-INODE-BITMAP-IOR "
                "CONSTANT _LR-INODE-BITMAP-HOME"
            ),
            (
                "_LR-CTX _EXT4-C.BLOCK + 2 + C@ 0x12 AND "
                "CONSTANT _LR-INODE-BITS"
            ),
            "0 _LR-CTX _EXT4-LOAD-DESC CONSTANT _LR-DESC-IOR",
            (
                _forth_conjunction(
                    [
                        "_LR-IOR 0=",
                        "_LR-V V.LIFECYCLE @ VFS-L-MOUNTED =",
                        "_LR-V _EXT4-READY?",
                        "_LR-V _EXT4-ATTACHED?",
                        "_LR-V V.FLAGS @ VFS-F-DIRTY AND 0=",
                        "_LR-CTX _EXT4-C.RECOVERY + @ 0=",
                        "_LR-CTX _EXT4-C.J.WRITE-ACTIVE + @ 0=",
                        "_LR-CTX _EXT4-C.J.PROTOCOL-OWNERS + @ -1 =",
                        "_LR-CTX _EXT4-C.J.WRITER-CURRENT + @ -1 =",
                        "_LR-CTX _EXT4-C.J.WRITER + @ 0=",
                        "_LR-CTX _EXT4-C.J.WRITER-STORE-KIND + @ 0=",
                        "_LR-CTX _EXT4-C.J.WRITER-ARENA + @ 0=",
                        "_LR-CTX _EXT4-C.J.HOME-WRITES + @ 1 =",
                        "_LR-CTX _EXT4-C.J.START + @ 0=",
                        "_LR-CTX _EXT4-C.J.WITNESS + @ 0=",
                        "_LR-CTX _EXT4-C.J.CLEANUP + @ 0=",
                        "_LR-CTX _EXT4-C.J.PRIMARY-TORN + @ 0=",
                        "_LR-CTX _EXT4-C.SUPER-TORN + @ 0=",
                        "_LR-CTX _EXT4-C.O.ACTIVE + @ 0=",
                        "_LR-CTX _EXT4-C.O.MODERN-ACTIVE + @ 0=",
                        "_LR-CTX _EXT4-C.O.LEGACY-ACTIVE + @ 0=",
                        "_LR-CTX _EXT4-C.O.CLEAR-PENDING + @ 0=",
                        "_LR-CTX _EXT4-C.ARENA + @ _LR-ARENA =",
                        (
                            "_LR-CTX _EXT4-C.SB + "
                            "_EXT4-SB.LAST-ORPHAN + L@ 0="
                        ),
                        (
                            "_LR-CTX _EXT4-C.SB + _EXT4-SB.INCOMPAT + L@ "
                            "_EXT4-INCOMPAT-RECOVER AND 0="
                        ),
                        (
                            "_LR-CTX _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@ "
                            "_EXT4-RO-ORPHAN-PRESENT AND 0="
                        ),
                        "_LR-I18-IOR 0=",
                        "_LR-I18-DTIME 0=",
                        "_LR-I18-LINKS 2 =",
                        "_LR-I18-SIZE-LO 0=",
                        "_LR-I18-SIZE-HI 0=",
                        "_LR-I18-BLOCKS-LO 0=",
                        "_LR-I18-BLOCKS-HI 0=",
                        "_LR-I18-ENTRIES 0=",
                        "_LR-I21-IOR 0=",
                        "_LR-I21-DTIME 0=",
                        "_LR-I21-LINKS 2 =",
                        "_LR-I21-ENTRIES 0=",
                        "_LR-DATA-BITMAP-IOR 0=",
                        (
                            "_LR-DATA-BITMAP-HOME "
                            f"{block_bitmap_home} ="
                        ),
                        "_LR-DATA-BIT 0=",
                        "_LR-INODE-BITMAP-IOR 0=",
                        (
                            "_LR-INODE-BITMAP-HOME "
                            f"{inode_bitmap_home} ="
                        ),
                        "_LR-INODE-BITS 0x12 =",
                        "_LR-DESC-IOR 0=",
                        "_EXT4-MOC-MARK-VALID @ 0=",
                        "_EXT4-MOC-MARK @ _LR-ARENA A.PTR @ =",
                        "_EXT4-MOC-WRITER @ 0=",
                        "_EXT4-MOC-TX @ 0=",
                        "_EXT4-JFO-CERT-SCOPE @ 0=",
                        "_EXT4-JFO-CERT-VALID @ 0=",
                        *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                        "_EXT4-MUTATION-OWNER-INO @ 0=",
                        "_EXT4-MUTATION-PROTOCOL-CTX @ 0=",
                        "_EXT4-MUTATION-PROTOCOL-ACTIVE @ 0=",
                        "_EXT4-MAP-VALIDATION-LIMIT @ 0=",
                    ]
                )
                + f' IF ." {marker}" THEN'
            ),
        ],
        capture_media=repaired,
        max_steps=_MULTI_ORPHAN_RECOVERY_MAX_STEPS,
    )
    _assert_emitted(output, marker)
    assert repaired.is_file()
    assert _sha256(repaired) == repaired_sha256
    for home in {
        1,
        inode18_home,
        inode21_home,
        block_bitmap_home,
        inode_bitmap_home,
        gdt_home,
        orphan_home,
        data_block,
    }:
        with clean_image.open("rb") as clean_media:
            clean_media.seek(home * block_size)
            expected = clean_media.read(block_size)
        with repaired.open("rb") as repaired_media:
            repaired_media.seek(home * block_size)
            observed = repaired_media.read(block_size)
        assert observed == expected
    assert not _write_ordinals_for_ext4_home(repair_trace, inode21_home)
    assert not _write_ordinals_for_ext4_home(repair_trace, inode_bitmap_home)
    orphan_repair_writes = _write_ordinals_for_ext4_home(
        repair_trace,
        orphan_home,
    )
    if protocol == "modern":
        assert orphan_repair_writes
    else:
        assert not orphan_repair_writes
    assert not _write_ordinals_for_ext4_home(repair_trace, data_block)

    stable_marker = f"EXT4-LINKED-{protocol_tag}-FIRST-MORE-CRASH-STABLE"
    stable_output, stable_trace, stable_sha256 = run_recovery_forth(
        repaired,
        stable,
        [
            "T-ARENA T-VOLUME EXT4-NEW CONSTANT _LS-IOR CONSTANT _LS-V",
            (
                _forth_conjunction(
                    [
                        "_LS-IOR 0=",
                        "_LS-V V.LIFECYCLE @ VFS-L-MOUNTED =",
                        "_LS-V _EXT4-READY?",
                        "_LS-V _EXT4-ATTACHED?",
                        "_LS-V V.FLAGS @ VFS-F-DIRTY AND 0=",
                        "_LS-V _EXT4-CTX _EXT4-C.J.WRITER + @ 0=",
                    ]
                )
                + f' IF ." {stable_marker}" THEN'
            ),
        ],
        capture_media=stable,
    )
    _assert_emitted(stable_output, stable_marker)
    assert stable_trace == ()
    assert stable_sha256 == repaired_sha256
    assert _sha256(stable) == repaired_sha256


def _linked_first_more_fault_probe(
    marker: str,
    *,
    partial: bool,
) -> list[str]:
    partial_check = "0<>" if partial else "0="
    return [
        "T-ARENA CONSTANT _LFC-ARENA",
        (
            "_LFC-ARENA T-VOLUME EXT4-NEW "
            "CONSTANT _LFC-IOR CONSTANT _LFC-V"
        ),
        "_LFC-V _EXT4-CTX CONSTANT _LFC-CTX",
        (
            _forth_conjunction(
                [
                    "_LFC-IOR VFS-IOR-DOMAIN VFS-IOR-D-VOLUME =",
                    "_LFC-IOR VFS-IOR-REASON VFS-R-IO =",
                    (
                        "_LFC-IOR VFS-IOR-FLAGS "
                        f"VFS-IOR-F-PARTIAL AND {partial_check}"
                    ),
                    "_LFC-V V.LAST-IOR @ _LFC-IOR =",
                    "_LFC-V V.LIFECYCLE @ VFS-L-NEW =",
                    "_LFC-V _EXT4-READY? 0=",
                    "_LFC-V V.FLAGS @ VFS-F-DIRTY AND 0<>",
                    "_LFC-CTX _EXT4-C.RECOVERY + @ 0<>",
                    "_LFC-CTX _EXT4-C.J.WRITER + @ 0=",
                    "_LFC-CTX _EXT4-C.J.WRITER-CURRENT + @ 0=",
                    "_LFC-CTX _EXT4-C.J.WRITE-ACTIVE + @ 0=",
                    "_LFC-CTX _EXT4-C.J.PROTOCOL-OWNERS + @ 0=",
                    "_LFC-CTX _EXT4-C.ARENA + @ _LFC-ARENA =",
                    "_EXT4-MOC-MARK-VALID @ 0=",
                    "_EXT4-MOC-MARK @ _LFC-ARENA A.PTR @ =",
                    "_EXT4-MOC-SPAN @ _EXT4-JWR-SIZE U< 0=",
                    (
                        "_EXT4-MOC-MARK @ _EXT4-MOC-SPAN @ "
                        "_EXT4-BYTES-ZERO?"
                    ),
                    "_EXT4-MOC-WRITER @ 0=",
                    "_EXT4-MOC-TX @ 0=",
                    "_EXT4-JFO-CERT-SCOPE @ 0=",
                    "_EXT4-JFO-CERT-VALID @ 0=",
                    *_EXT4_MUTATION_OWNER_RANGES_CLEAN_FORTH,
                    "_EXT4-MUTATION-OWNER-INO @ 0=",
                    "_EXT4-MUTATION-PROTOCOL-CTX @ 0=",
                    "_EXT4-MUTATION-PROTOCOL-ACTIVE @ 0=",
                    "_EXT4-MAP-VALIDATION-LIMIT @ 0=",
                ]
            )
            + f' IF ." {marker}" THEN'
        ),
    ]


def _patched_ext4_home(
    source: Path,
    patches: tuple[tuple[int, bytes], ...],
    home: int,
    *,
    block_size: int,
) -> bytes:
    offset = home * block_size
    with source.open("rb") as source_media:
        source_media.seek(offset)
        result = bytearray(source_media.read(block_size))
    assert len(result) == block_size
    for patch_offset, patch_data in patches:
        overlap_start = max(offset, patch_offset)
        overlap_end = min(offset + block_size, patch_offset + len(patch_data))
        if overlap_start >= overlap_end:
            continue
        result[overlap_start - offset : overlap_end - offset] = patch_data[
            overlap_start - patch_offset : overlap_end - patch_offset
        ]
    return bytes(result)


def _read_ext4_home(path: Path, home: int, *, block_size: int) -> bytes:
    with path.open("rb") as media:
        media.seek(home * block_size)
        result = media.read(block_size)
    assert len(result) == block_size
    return result


